from __future__ import annotations

import logging
from abc import ABCMeta, abstractmethod

import requests

from ..exceptions import PduConnectionError
from .base import PDU


class HttpPdu(PDU, metaclass=ABCMeta):
    """Class that makes it possible to
    manage a single PDU device over the HTTP protocol."""

    def __init__(self, host: str, timeout: float | str) -> None:
        super(HttpPdu, self).__init__(host)
        self._timeout = float(timeout)

    @abstractmethod
    def _build_request_url(self, port, status):
        """Build command for HTTP-based PDU set status"""

    @abstractmethod
    def _parse_response(self, response, port):
        """Parser for response from PDU"""

    def _set_port_status(self, port, status):
        logging.info(f"HTTP: Setting port to {status}: {port}")
        request_url = self._build_request_url(port, status)
        self._send_request(request_url)

    def get_port_status(self, port):
        logging.info(f"HTTP: Fetching status of port: {port}")
        request_url = self._build_request_url(port, None)
        response = self._send_request(request_url)
        parsed_response = self._parse_response(response, port)
        return self._reversed_port_settings[parsed_response]

    def _send_request(
        self, url, method="GET", headers=None, data=None, params=None, proxies=None
    ) -> requests.Response:
        try:
            return requests.request(
                method=method,
                url=url,
                headers=headers,
                data=data,
                params=params,
                proxies=proxies,
            )
        except requests.exceptions.ConnectionError as e:
            logging.error(str(e))
            exc_msg = f"Cannot send request to url={url}"
            raise PduConnectionError(exc_msg)
